    cin >> N >> L >> T;

    vector<int64> X(N), W(N);
    for (int i = 0; i < N; ++i) cin >> X[i] >> W[i];

    // Final positions if ants pass through each other.
    vector<int64> pos(N);
    for (int i = 0; i < N; ++i) {
        if (W[i] == 1) pos[i] = (X[i] + T) % L;          // clockwise
        else pos[i] = ((X[i] - T) % L + L) % L;          // counterclockwise
    }

    vector<int64> sortedPos = pos;
    sort(sortedPos.begin(), sortedPos.end());

    // Compute where ant 0's label ends up in the cyclic order.
    // Each meeting between ant 0 and another ant shifts its label by:
    // +1 if ant 0 moves clockwise, -1 if counterclockwise.
    long long shift = 0;

    if (W[0] == 1) {
        for (int i = 1; i < N; ++i) {
            if (W[i] == 2) {
                long long d = (X[i] - X[0] + L) % L;
                shift += (2 * T - d + L - 1) / L;
            }
        }
    } else {
        for (int i = 1; i < N; ++i) {
            if (W[i] == 1) {
                long long d = (X[0] - X[i] + L) % L;
                shift -= (2 * T - d + L - 1) / L;
            }
        }
    }

    // Find ant 0's final physical position among sorted positions.
    int64 p0 = pos[0];
    int idxPhys;
    if (W[0] == 1) {
        idxPhys = lower_bound(sortedPos.begin(), sortedPos.end(), p0) - sortedPos.begin();
    } else {
        idxPhys = upper_bound(sortedPos.begin(), sortedPos.end(), p0) - sortedPos.begin() - 1;
    }

    long long idxLabel = ((long long)idxPhys - shift) % N;
    if (idxLabel < 0) idxLabel += N;

    // Assign labels in original order starting from ant 0.
    vector<int64> ans(N);
    for (int k = 0; k < N; ++k) {
        ans[(k % N)] = sortedPos[(idxLabel + k) % N];
    }

    for (int i = 0; i < N; ++i) {
        cout << ans[i] << '\n';
    }

    return 0;
}

