typedef long long ll;

typedef struct {
    ll pos;
    int idx;
} Node;

int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int cmp_node(const void *a, const void *b) {
    const Node *x = (const Node *)a;
    const Node *y = (const Node *)b;
    if (x->pos < y->pos) return -1;
    if (x->pos > y->pos) return 1;
    return x->idx - y->idx;
}

static ll modll(ll a, ll m) {
    a %= m;
    if (a < 0) a += m;
    return a;
}

int main(void) {
    int N;
    ll L, T;
    if (scanf("%d %lld %lld", &N, &L, &T) != 3) return 0;

    ll *X = (ll *)malloc(sizeof(ll) * N);
    int *W = (int *)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++) {
        scanf("%lld %d", &X[i], &W[i]);
    }

    if (N == 1) {
        ll ans;
        if (W[0] == 1) ans = modll(X[0] + T, L);
        else ans = modll(X[0] - T, L);
        printf("%lld\n", ans);
        free(X);
        free(W);
        return 0;
    }

    ll *finalPos = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) {
        if (W[i] == 1) finalPos[i] = modll(X[i] + T, L);
        else finalPos[i] = modll(X[i] - T, L);
    }

    qsort(finalPos, N, sizeof(ll), cmp_ll);

    /*
      Key fact:
      Ants are indistinguishable under collision (equivalent to passing through),
      so the multiset of final positions is just finalPos[].

      We only need the cyclic shift of labels.

      Compute where ant 0's label ends up among the sorted final positions.
    */
    ll x0 = X[0];
    int w0 = W[0];

    ll y0 = (w0 == 1) ? x0 + T : x0 - T;
    ll y0mod = modll(y0, L);

    ll shift = 0;

    for (int i = 1; i < N; i++) {
        if (w0 == 1 && W[i] == 2) {
            ll d = modll(X[i] - x0, L);
            ll cnt = (2 * T + (L - d)) / L;
            shift += cnt;
        } else if (w0 == 2 && W[i] == 1) {
            ll d = modll(x0 - X[i], L);
            ll cnt = (2 * T + (L - d)) / L;
            shift -= cnt;
        }
    }

    shift %= N;
    if (shift < 0) shift += N;

    /*
      Find the base rank of ant 0's ghost position among sorted final positions.
      If duplicates exist, tie handling depends on direction:
      - clockwise ant gets the last occurrence among equals after positive shifts
      - counterclockwise ant gets the first occurrence among equals after negative shifts
      Standard approach:
        find range [lb, ub] of y0mod in finalPos.
        rank = lb for CCW, ub for CW, then apply shift.
    */
    int lb = 0, ub = -1;

    int l = 0, r = N;
    while (l < r) {
        int m = (l + r) >> 1;
        if (finalPos[m] >= y0mod) r = m;
        else l = m + 1;
    }
    lb = l;

    l = 0; r = N;
    while (l < r) {
        int m = (l + r) >> 1;
        if (finalPos[m] > y0mod) r = m;
        else l = m + 1;
    }
    ub = l - 1;

    int rank0;
    if (w0 == 1) rank0 = ub;
    else rank0 = lb;

    rank0 = (rank0 + (int)shift) % N;

    ll *ans = (ll *)malloc(sizeof(ll) * N);
    for (int i = 0; i < N; i++) {
        ans[(0 + i) % N] = finalPos[(rank0 + i) % N];
    }

    for (int i = 0; i < N; i++) {
        printf("%lld\n", ans[i]);
    }

    free(X);
    free(W);
    free(finalPos);
    free(ans);
    return 0;
}

