    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long L = sc.nextLong();
        int N = sc.nextInt();
        long T = sc.nextLong();
        long[] X = new long[N];
        int[] D = new int[N]; // +1 clockwise, -1 counterclockwise
        for (int i = 0; i < N; i++) {
            X[i] = sc.nextLong();
            String dir = sc.next();
            D[i] = dir.equals("CW") ? 1 : -1;
        }
        Integer[] idx = new Integer[N];
        for (int i = 0; i < N; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Long.compare(X[a], X[b]));
        long[] ghost = new long[N];
        for (int i = 0; i < N; i++) ghost[i] = ((X[i] + (long)D[i] * T) % L + L) % L;
        long[] sortedGhost = ghost.clone();
        Arrays.sort(sortedGhost);
        long[] ans = new long[N];
        for (int ii = 0; ii < N; ii++) {
            int i = idx[ii];
            long xi = X[i]; int di = D[i];
            long passed = 0;
            for (int jj = 0; jj < N; jj++) {
                if (ii == jj) continue;
                int j = idx[jj];
                long xj = X[j]; int dj = D[j];
                if (di == 1 && dj == -1) { long dist = (xj - xi + L) % L; if (dist <= T) passed++; }
                else if (di == -1 && dj == 1) { long dist = (xi - xj + L) % L; if (dist <= T) passed++; }
            }
            int newPos = (int)((ii + passed) % N);
            ans[i] = sortedGhost[newPos];
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) sb.append(ans[i]).append("\n");
        System.out.print(sb);
    }
}

