public class AntsOnCircle {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long T = Long.parseLong(st.nextToken());

        long[] positions = new long[N];
        int[] directions = new int[N];
        Integer[] indices = new Integer[N];

        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            positions[i] = Long.parseLong(st.nextToken());
            directions[i] = Integer.parseInt(st.nextToken());
            indices[i] = i;
        }

        // Sort indices by starting position
        Arrays.sort(indices, Comparator.comparingLong(i -> positions[i]));

        // Calculate final positions ignoring collisions
        long[] finalPositions = new long[N];
        long offset = 0;
        for (int i = 0; i < N; i++) {
            long x = positions[i];
            int dir = directions[i];
            if (dir == 1) { // clockwise
                finalPositions[i] = (x + T) % L;
                offset += (x + T) / L;
            } else { // counterclockwise
                finalPositions[i] = ((x - T) % L + L) % L;
                offset += (x - T) >= 0 ? 0 : -1 + ((x - T) % L == 0 ? 0 : 0);
                // Actually better to compute offset properly:
            }
        }

        // Recompute offset properly
        offset = 0;
        for (int i = 0; i < N; i++) {
            if (directions[i] == 1) {
                offset += (positions[i] + T) / L;
            } else {
                offset += (positions[i] - T - 1) / L; // floor division for negative
            }
        }

        // Normalize offset
        offset = ((offset % N) + N) % N;

        // Sort final positions
        Arrays.sort(finalPositions);

        // Rotate the sorted final positions by offset
        long[] rotated = new long[N];
        for (int i = 0; i < N; i++) {
            rotated[(int)((i + offset) % N)] = finalPositions[i];
        }

        // Assign back in original index order
        long[] result = new long[N];
        for (int i = 0; i < N; i++) {
            result[indices[i]] = rotated[i];
        }

        StringBuilder sb = new StringBuilder();
        for (long pos : result) {
            sb.append(pos).append("\n");
        }
        System.out.print(sb);
    }
}

