public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Ant {
        long x;
        int w; // 1: clockwise, 2: counterclockwise
        int idx;

        Ant(long x, int w, int idx) {
            this.x = x;
            this.w = w;
            this.idx = idx;
        }
    }

    static long mod(long a, long m) {
        long r = a % m;
        if (r < 0) r += m;
        return r;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long L = fs.nextLong();
        long T = fs.nextLong();

        Ant[] ants = new Ant[N];
        long[] X = new long[N];
        int[] W = new int[N];

        for (int i = 0; i < N; i++) {
            long x = fs.nextLong();
            int w = fs.nextInt();
            ants[i] = new Ant(x, w, i);
            X[i] = x;
            W[i] = w;
        }

        // Compute final positions if ants pass through each other.
        long[] pos = new long[N];
        for (int i = 0; i < N; i++) {
            if (W[i] == 1) pos[i] = mod(X[i] + T, L);
            else pos[i] = mod(X[i] - T, L);
        }

        Arrays.sort(pos);

        // Determine where ant 0's label ends up among sorted final positions.
        long basePos = (W[0] == 1) ? mod(X[0] + T, L) : mod(X[0] - T, L);

        long shift = 0;
        for (int i = 1; i < N; i++) {
            long d;
            if (W[0] == 1 && W[i] == 2) {
                d = X[i] - X[0];
                if (d < 0) d += L;
                shift += (2 * T + L - d) / L;
            } else if (W[0] == 2 && W[i] == 1) {
                d = X[0] - X[i];
                if (d < 0) d += L;
                shift -= (2 * T + L - d) / L;
            }
        }

        // Find the position index of ant 0 in sorted final positions.
        int k;
        if (W[0] == 1) {
            k = lowerBound(pos, basePos);
            k = (int) mod(k + shift, N);
        } else {
            k = upperBound(pos, basePos) - 1;
            k = (int) mod(k + shift, N);
        }

        long[] ans = new long[N];
        for (int i = 0; i < N; i++) {
            ans[i] = pos[(k + i) % N];
        }

        StringBuilder sb = new StringBuilder();
        for (long v : ans) sb.append(v).append('\n');
        System.out.print(sb.toString());
    }

    static int lowerBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] >= key) r = m;
            else l = m + 1;
        }
        return l;
    }

    static int upperBound(long[] a, long key) {
        int l = 0, r = a.length;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] > key) r = m;
            else l = m + 1;
        }
        return l;
    }
